// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint _val) public {
        // Initialize the contract
        c.SetMinSum(100);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // After initialization, SetMinSum should revert (reference behavior)
        // The bug makes it not revert, allowing MinSum to change
        vm.assume(_val != 100); // so we can detect a change

        // Record MinSum before the attempted call
        uint before = c.MinSum();

        // This call must revert in the reference; if it succeeds, the bug is present
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.SetMinSum.selector, _val));

        // General rule: SetMinSum must revert after Initialized
        assertTrue(!ok, "SetMinSum should revert after initialization");
    }
}

